export type StoreLanguage = "en" | "te" | "hi";

export const languageNames: Record<StoreLanguage, string> = {
  en: "English",
  te: "తెలుగు",
  hi: "हिन्दी",
};

export function readStoreLanguage(): StoreLanguage {
  try {
    const saved = localStorage.getItem("kq-language");
    return saved === "te" || saved === "hi" ? saved : "en";
  } catch {
    return "en";
  }
}

